//! Replays `fixtures/checkpoint.jsonl`, generated by `rust/tools/generate_checkpoint_fixtures.mjs`
//! from the original checkpointing/Utils.ts and Diffs.ts.
use serde_json::Value;
use t3_vcs::{
    TurnDiffFileSummary, checkpoint::parse_numstat_with_locale, checkpoint_ref_for_thread_turn,
    parse_turn_diff_files_from_numstat,
};

fn rows() -> Vec<Value> {
    include_str!("fixtures/checkpoint.jsonl")
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect()
}

fn summaries(value: &Value) -> Vec<TurnDiffFileSummary> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|file| TurnDiffFileSummary {
            path: file["path"].as_str().unwrap().into(),
            additions: file["additions"].as_u64().unwrap(),
            deletions: file["deletions"].as_u64().unwrap(),
        })
        .collect()
}

#[test]
fn checkpoint_refs_match_the_original_naming() {
    let mut checked = 0;
    for row in rows().iter().filter(|row| row["type"] == "ref") {
        let actual = checkpoint_ref_for_thread_turn(
            row["threadId"].as_str().unwrap(),
            row["turnCount"].as_u64().unwrap(),
        );
        assert_eq!(actual, row["ref"].as_str().unwrap(), "{row}");
        checked += 1;
    }
    assert_eq!(checked, 105);
}

#[test]
fn numstat_parsing_and_ordering_match_the_original() {
    let mut checked = 0;
    for row in rows().iter().filter(|row| row["type"] == "numstat") {
        let actual = parse_numstat_with_locale(
            row["numstat"].as_str().unwrap(),
            row["locale"].as_str().unwrap(),
        );
        assert_eq!(actual, summaries(&row["files"]), "{row}");
        checked += 1;
    }
    assert_eq!(checked, 14);
}

#[test]
fn numstat_parsing_with_the_process_locale_keeps_every_file() {
    // The environment locale may differ from the fixture's, so only the order is locale-bound.
    for row in rows().iter().filter(|row| row["type"] == "numstat") {
        let mut actual: Vec<_> =
            parse_turn_diff_files_from_numstat(row["numstat"].as_str().unwrap())
                .into_iter()
                .map(|file| (file.path, file.additions, file.deletions))
                .collect();
        let mut expected: Vec<_> = summaries(&row["files"])
            .into_iter()
            .map(|file| (file.path, file.additions, file.deletions))
            .collect();
        actual.sort();
        expected.sort();
        assert_eq!(actual, expected);
    }
}
